import json,glob
for f in glob.glob('*.network'):
    for line in open(f):
        e=json.loads(line)
        s=e.get('snapshot',{})
        r=s.get('request',{})
        if '/claims' in r.get('url','') and r.get('method')!='GET':
            print(r['method'], r['url'][-60:], s.get('response',{}).get('status'), (r.get('postData') or {}).get('text','')[:150])
EOF

